<script setup lang="ts">
import {onMounted,onBeforeUnmount,reactive,ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {createModelImport,getModelImport,listModelImports,controlModelImport,importLabels,importActive} from '../api/modelImports'
import type {ModelImport} from '../types'
import {useDemoStore} from '../stores/demo'
const route=useRoute(),router=useRouter(),store=useDemoStore()
const form=reactive({name:'',github:'',weights:'',revision:'',python:'python3'})
const root=ref('加载管理目录…'),current=ref<ModelImport|null>(null),error=ref(''),busy=ref(false),available=ref(false)
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false
const phases=['cloning','downloading','analyzing','installing','checking']
const phaseIndex=computed(()=>phases.indexOf(current.value?.status??''))
async function poll(){if(disposed||!current.value)return;try{current.value=await getModelImport(current.value.id);error.value='';if(current.value.status==='ready')await store.syncImportedModels()}catch(e){error.value=e instanceof Error?e.message:'状态更新失败。'}finally{if(!disposed&&current.value&&importActive(current.value.status))timer=setTimeout(poll,1800)}}
async function load(){clearTimeout(timer);error.value='';try{const data=await listModelImports();root.value=data.root;available.value=true;if(typeof route.query.import==='string'){current.value=await getModelImport(route.query.import);if(importActive(current.value.status))timer=setTimeout(poll,1000)}else current.value=null}catch(e){available.value=false;error.value=e instanceof Error?e.message:'导入服务不可用。'}}
onMounted(load);watch(()=>route.query.import,load);onBeforeUnmount(()=>{disposed=true;clearTimeout(timer)})
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{current.value=await createModelImport({...form});await router.replace({path:'/models/new',query:{import:current.value.id}})}catch(e){error.value=e instanceof Error?e.message:'创建失败。'}finally{busy.value=false}}
async function action(type:'retry'|'cancel'){if(!current.value||busy.value)return;busy.value=true;error.value='';try{current.value=await controlModelImport(current.value.id,type);clearTimeout(timer);timer=setTimeout(poll,500)}catch(e){error.value=e instanceof Error?e.message:'操作失败。'}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">ROBOTIC LAB / 模型管理</div><h1>{{current?'模型导入':'新建模型'}}<span class="heading-dot">.</span></h1><p>从代码仓库与权重仓库构建模型运行环境。</p></div><button class="button" @click="router.push('/models')">返回模型管理</button></div><div class="import-mode">真实导入 · 文件将保存到当前服务所在容器；训练功能仍为 Mock。</div><div v-if="error" class="form-error" role="alert">{{error}} <button v-if="!current" class="text-link" @click="load">重新连接</button></div>
<form v-if="!current" class="import-form" @submit.prevent="submit"><div class="form-grid"><label class="wide">模型名称<input v-model="form.name" placeholder="例如：Pi0.5 项目环境" required maxlength="80"/></label><label class="wide">GitHub 代码仓库<input v-model="form.github" type="url" placeholder="https://github.com/owner/repository" required/><small>填写公开仓库首页，服务会拉取默认分支。</small></label><label class="wide">Hugging Face / ModelScope 权重仓库<input v-model="form.weights" type="url" placeholder="https://huggingface.co/owner/model" required/><small>也支持 https://modelscope.cn/models/owner/model，填写仓库首页。</small></label><label>权重版本（可选）<input v-model="form.revision" placeholder="默认版本 / 分支 / commit"/></label><label>基础 Python<select v-model="form.python"><option value="python3">容器默认 python3</option><option>python3.10</option><option>python3.11</option><option>python3.12</option><option>python3.13</option></select><small>需已安装在容器内；不会替换系统 Python。</small></label></div><div class="import-destination"><strong>模型管理目录</strong><code>{{root}}</code><p>每个模型独立保存：code/ 代码、weights/ 权重、.venv/ 环境、import.json 导入记录。</p></div><div class="import-policy"><p>提交后自动下载代码和完整权重，并在独立虚拟环境内执行 README 中可识别的 pip 安装步骤。安装过程会运行仓库的 Python 安装代码，请使用可信仓库。</p><p>涉及 Conda、CUDA、系统依赖或自定义脚本的步骤会暂停自动配置并显示处理说明。私有或受限权重需提前在服务端配置访问凭据。</p></div><div class="form-actions"><span class="muted">权重下载可能占用较大磁盘空间。</span><button class="button primary" :disabled="busy||!available">{{busy?'正在创建…':'开始导入并配置'}}</button></div></form>
<template v-else><div class="import-title"><div><h2>{{current.name}}</h2><span :class="['import-status',current.status]">{{importLabels[current.status]??current.status}}</span></div><div class="row-actions"><button v-if="importActive(current.status)" class="button danger" :disabled="busy" @click="action('cancel')">取消导入</button><button v-else-if="current.status!=='ready'" class="button" :disabled="busy" @click="action('retry')">重试导入</button><button v-else class="button primary" @click="router.push('/models')">查看模型</button></div></div><div class="import-phases"><span v-for="(phase,index) in phases" :key="phase" :class="{current:phaseIndex===index,done:current.status==='ready'||phaseIndex>index}"><b>{{index+1}}</b>{{importLabels[phase]}}</span></div><div v-if="current.error" class="form-error">{{current.error}}<p v-if="current.status==='needs_attention'">代码和权重已保留，请按下方 README 完成未支持的步骤。不会将此环境标为就绪。</p></div><dl class="review-grid"><div><dt>代码仓库</dt><dd><a :href="current.github.replace(/\.git$/,'')" target="_blank" rel="noreferrer">{{current.github}}</a></dd></div><div><dt>权重仓库</dt><dd><a :href="current.weights" target="_blank" rel="noreferrer">{{current.weights}}</a></dd></div><div><dt>代码目录</dt><dd>{{current.paths.code??'等待创建'}}</dd></div><div><dt>权重目录</dt><dd>{{current.paths.weights??'等待创建'}}</dd></div><div><dt>Python 环境</dt><dd>{{current.paths.environment??'等待创建'}}</dd></div><div><dt>Git commit</dt><dd>{{current.commit??'等待拉取'}}</dd></div></dl><section class="panel" style="margin-top:22px"><div class="log-head"><h2>导入日志</h2><span class="muted">{{importActive(current.status)?'自动更新':'已停止更新'}} · 最近 400 行</span></div><pre class="log-terminal">{{current.logs.join('\n')||'正在等待服务响应…'}}</pre></section><section v-if="current.plan" class="readme-plan"><h2>README 环境配置</h2><p>识别到的标准安装步骤：</p><pre class="command-preview">{{current.plan.commands.map(c=>c.label).join('\n')||'无可自动执行步骤'}}</pre><template v-if="current.plan.unsupported.length"><p>以下步骤需人工处理，自动安装未执行：</p><pre class="command-preview">{{current.plan.unsupported.join('\n')}}</pre></template><details><summary>查看 {{current.readmeFile||'README'}} 原文</summary><pre class="readme-text">{{current.readme||'仓库根目录未找到 README。'}}</pre></details></section></template></template>
<style scoped>.import-form .form-grid,.review-grid{grid-template-columns:minmax(0,1fr)}.import-form .form-grid .wide{grid-column:auto}.import-mode{font-size:11px;color:#8a6c35;margin-bottom:24px}.import-form{max-width:850px;border-top:1px solid var(--border);padding-top:24px}.import-destination{margin:24px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:17px 0;font-size:12px}.import-destination strong{display:block;margin-bottom:9px;font-weight:500}.import-destination code{font-size:11px;overflow-wrap:anywhere}.import-destination p,.import-policy p{font-size:11px;line-height:1.9;color:var(--muted);margin-top:9px}.form-actions>span{font-size:10px}.form-actions button:disabled{opacity:.5}.import-title{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:22px}.import-title>div:first-child{display:flex;gap:15px;align-items:center}.import-title h2{font-size:19px}.import-status{font-size:11px;color:var(--blue)}.import-status.failed,.import-status.needs_attention{color:#bd624c}.import-status.ready{color:#31a180}.import-phases{display:flex;gap:15px;flex-wrap:wrap;padding:18px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border);margin-bottom:20px}.import-phases span{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--muted);flex:1;white-space:nowrap}.import-phases b{display:grid;place-items:center;border:1px solid var(--border);border-radius:50%;width:24px;height:24px;font-weight:400}.import-phases .current{color:var(--blue)}.import-phases .current b{border-color:var(--blue)}.import-phases .done{color:#31a180}.review-grid a{color:var(--blue)}.readme-plan{margin-top:25px}.readme-plan h2{font-size:15px}.readme-plan p{font-size:12px;color:var(--muted);margin:15px 0}.readme-plan summary{font-size:12px;cursor:pointer}.readme-text{white-space:pre-wrap;overflow-wrap:anywhere;font:11px/1.8 ui-monospace,monospace;padding:20px;background:var(--subtle);border:1px solid var(--border);border-radius:7px;max-height:500px;overflow:auto}@media(max-width:700px){.import-title{flex-wrap:wrap}.import-title>div:first-child{flex-wrap:wrap}.import-phases span{flex:1 0 40%}}</style>
